import PropTypes from 'prop-types';

// material-ui
import { useTheme } from '@mui/material/styles';
import { Divider, List, Typography } from '@mui/material';

// project imports
import NavItem from '../NavItem';
import NavCollapse from '../NavCollapse';

// ==============================|| SIDEBAR MENU LIST GROUP ||============================== //

const NavGroup = ({ item }) => {
    const theme = useTheme();

    // Custom styles for smaller menu
    const smallMenuStyles = {
        groupTitle: {
            ...theme.typography.menuCaption,
            fontSize: '0.7rem', // Smaller group title
            color: theme.palette.text.primary,
            listStyleType: 'none'
        },
        groupCaption: {
            ...theme.typography.subMenuCaption,
            fontSize: '0.65rem' // Smaller caption
        },
        item: {
            fontSize: '0.8rem' // Smaller menu items
        },
        icon: {
            fontSize: '1rem !important' // Smaller icons
        }
    };

    // menu list collapse & items
    const items = item.children?.map((menu) => {
        switch (menu.type) {
            case 'collapse':
                return (
                    <NavCollapse key={menu.id} menu={menu} level={1} textStyle={smallMenuStyles.item} iconStyle={smallMenuStyles.icon} />
                );
            case 'item':
                return <NavItem key={menu.id} item={menu} level={1} textStyle={smallMenuStyles.item} iconStyle={smallMenuStyles.icon} />;
            default:
                return (
                    <Typography key={menu.id} variant="h6" color="error" align="center">
                        Menu Items Error
                    </Typography>
                );
        }
    });

    return (
        <>
            <List
                disablePadding
                subheader={
                    item.title && (
                        <Typography variant="caption" sx={smallMenuStyles.groupTitle} display="block" gutterBottom>
                            {item.title}
                            {item.caption && (
                                <Typography variant="caption" sx={smallMenuStyles.groupCaption} display="block" gutterBottom>
                                    {item.caption}
                                </Typography>
                            )}
                        </Typography>
                    )
                }
            >
                {items}
            </List>
        </>
    );
};

NavGroup.propTypes = {
    item: PropTypes.object
};

export default NavGroup;
