import { memo } from 'react';

// project imports
import NavGroup from './NavGroup';
import menuItem from 'menu-items';
import useAuth from 'hooks/useAuth';

const menuItemStyles = {
    typography: {
        fontSize: '0.8rem' // Smaller text
    },
    icon: {
        fontSize: '1rem' // Smaller icons
    }
};
const MenuList = () => {
    const { permissions } = useAuth(); // Get user permissions

    // 🔹 Function to check if the user has permission
    const hasPermission = (requiredPermission) => {
        if (!requiredPermission) return true; // ✅ Allow items without permission checks
        return permissions.some((perm) => perm.name === requiredPermission);
    };

    // 🔹 Recursive function to filter menus, submenus & features based on permissions
    const filterMenuItems = (items, parentPermission = null) =>
        items
            .map((item) => {
                const userHasParentPermission = parentPermission ? hasPermission(parentPermission) : true;
                const userHasCurrentPermission = item.permission ? hasPermission(item.permission) : true;

                // 🔥 If the parent is restricted, hide this menu & its children
                if (!userHasParentPermission) {
                    return null;
                }

                if (item.children) {
                    // 🔹 Filter child menu items recursively
                    const filteredChildren = filterMenuItems(item.children, item.permission);

                    // 🔥 Hide parent if it has no visible children
                    if (filteredChildren.length === 0 && !userHasCurrentPermission) {
                        return null;
                    }

                    return { ...item, children: filteredChildren };
                }

                // 🔹 Check standalone items & submenus
                if (!userHasCurrentPermission) {
                    return null;
                }

                return item;
            })
            .filter(Boolean); // 🔹 Remove `null` values

    // 🔹 Filter the full menu based on permissions
    const filteredNavItems = filterMenuItems(menuItem.items).map((item) =>
        item.type === 'group' ? <NavGroup key={item.id} item={item} /> : null
    );

    return <>{filteredNavItems}</>;
};

export default memo(MenuList);
