import PropTypes from 'prop-types';
import { useEffect, useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

// project imports
import useAuth from 'hooks/useAuth';
import Loader from 'ui-component/Loader';

/**
 * Auth guard for routes that require authentication.
 * @param {PropTypes.node} children - Protected content.
 * @param {string} [requiredPermission] - The required permission to access the route.
 */
const AuthGuard = ({ children, requiredPermission }) => {
    const { isLoggedIn, isInitialized, permissions } = useAuth();
    const navigate = useNavigate();
    const location = useLocation();
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (!isInitialized) return; // ✅ Wait until authentication is initialized

        if (!isLoggedIn && location.pathname !== '/login') {
            // ✅ Redirect to login if not logged in
            navigate('/login', { replace: true });
        } else if (isLoggedIn) {
            // ✅ Check for required permission only if it's specified
            if (requiredPermission && !permissions.some((perm) => perm.name === requiredPermission)) {
                console.warn(`Access Denied: Redirecting to /dashboard/default`);
                navigate('/dashboard/default', { replace: true }); // ✅ Redirect if user lacks permission
            } else {
                setLoading(false); // ✅ Allow access if no permission is required or permission is granted
            }
        }
    }, [isInitialized, isLoggedIn, permissions, requiredPermission, navigate, location]);

    if (!isInitialized || loading) {
        return <Loader />; // ✅ Show loader while checking authentication
    }

    return children;
};

AuthGuard.propTypes = {
    children: PropTypes.node,
    requiredPermission: PropTypes.string
};

export default AuthGuard;
