import PropTypes from 'prop-types';
import { createContext, useEffect, useReducer } from 'react';

// third-party
import { Chance } from 'chance';
import jwtDecode from 'jwt-decode';

// reducer - state management
import { LOGIN, LOGOUT } from 'store/actions';
import accountReducer from 'store/accountReducer';

// project imports
import Loader from 'ui-component/Loader';
import axios from 'utils/axios';
import ApiRequest from 'utils/apiService';

const chance = new Chance();

// constant
const initialState = {
    isLoggedIn: false,
    isInitialized: false,
    user: null
};

const verifyToken = (serviceToken) => {
    if (!serviceToken) {
        return false;
    }
    const decoded = jwtDecode(serviceToken);
    /**
     * Property 'exp' does not exist on type '<T = unknown>(token, options?: JwtDecodeOptions | undefined) => T'.
     */
    return decoded.exp > Date.now() / 1000;
};

const setSession = (serviceToken) => {
    if (serviceToken) {
        localStorage.setItem('serviceToken', serviceToken);
        axios.defaults.headers.common.Authorization = `Bearer ${serviceToken}`;
    } else {
        localStorage.removeItem('serviceToken');
        delete axios.defaults.headers.common.Authorization;
    }
};

// ==============================|| JWT CONTEXT & PROVIDER ||============================== //
const JWTContext = createContext(null);

export const JWTProvider = ({ children }) => {
    const [state, dispatch] = useReducer(accountReducer, initialState);

    useEffect(() => {
        const init = async () => {
            try {
                const serviceToken = window.localStorage.getItem('serviceToken');

                if (serviceToken && verifyToken(serviceToken)) {
                    setSession(serviceToken);

                    const storedUser = JSON.parse(localStorage.getItem('user') || '{}');
                    const storedRoles = JSON.parse(localStorage.getItem('userRoles') || '[]');
                    const storedPermissions = JSON.parse(localStorage.getItem('userPermissions') || '[]');
                    // const lastPermissionUpdate = localStorage.getItem('lastPermissionUpdate');

                    // ✅ Use stored permissions first
                    dispatch({
                        type: LOGIN,
                        payload: {
                            isLoggedIn: true,
                            user: storedUser,
                            roles: storedRoles.length ? storedRoles : [], // Default to empty array
                            permissions: storedPermissions.length ? storedPermissions : [] // Default to empty array
                        }
                    });

                    // // 🚀 Check if 1 hour has passed since last permission update
                    // const oneHour = 60 * 60 * 1000;
                    // if (!lastPermissionUpdate || Date.now() - lastPermissionUpdate > oneHour) {
                    //     console.log('🔄 Refreshing permissions...');
                    //     const permissionsResponse = await axios.get('auth/permissions', {
                    //         headers: { Authorization: `Bearer ${serviceToken}` }
                    //     });

                    //     const permissions = permissionsResponse.data;

                    //     // ✅ Update `localStorage`
                    //     localStorage.setItem('userPermissions', JSON.stringify(permissions));
                    //     localStorage.setItem('lastPermissionUpdate', Date.now());

                    //     // ✅ Update Redux state with fresh permissions
                    //     dispatch({
                    //         type: LOGIN,
                    //         payload: {
                    //             isLoggedIn: true,
                    //             user: storedUser,
                    //             roles: storedRoles,
                    //             permissions
                    //         }
                    //     });
                    // }
                } else {
                    dispatch({ type: LOGOUT });
                }
            } catch (err) {
                console.error('Session restore failed:', err);
                dispatch({ type: LOGOUT });
            }
        };

        init();
    }, []);

    const login = async (email, password) => {
        const response = await ApiRequest('POST', 'auth/login', {
            email,
            password
        });
        const { access_token: serviceToken, user } = response.data;
        const userRoles = user.roleIds || []; // Default to empty array if missing
        const userPermissions = user.permissions || []; // Default to empty array if missing

        localStorage.setItem('user', JSON.stringify(user));
        localStorage.setItem('userRolesIds', JSON.stringify(userRoles));
        localStorage.setItem('userPermissions', JSON.stringify(userPermissions));
        // localStorage.setItem('lastPermissionUpdate', Date.now()); // ✅ Store timestamp

        setSession(serviceToken);
        dispatch({
            type: LOGIN,
            payload: {
                isLoggedIn: true,
                user,
                roles: user.roleIds,
                permissions: user.permissions
            }
        });

        console.log('redirect to dashboard');
    };

    const register = async (email, password, firstName, lastName) => {
        // todo: this flow need to be recode as it not verified
        const response = await ApiRequest('POST', `auth/signup`, {
            email,
            password,
            first_name: firstName,
            last_name: lastName,
            name: `${firstName} ${lastName}`,
            roles: [{ id: 3, name: 'client' }]
        });

        return response.data;
    };

    const logout = () => {
        setSession(null);
        localStorage.removeItem('user');
        localStorage.removeItem('userRolesIds');
        localStorage.removeItem('userPermissionsIds');
        dispatch({ type: LOGOUT });
    };

    const resetPassword = (email) => console.log(email);

    const updateProfile = () => {};

    if (state.isInitialized !== undefined && !state.isInitialized) {
        return <Loader />;
    }

    return (
        <JWTContext.Provider value={{ ...state, login, logout, register, resetPassword, updateProfile }}>{children}</JWTContext.Provider>
    );
};

JWTProvider.propTypes = {
    children: PropTypes.node
};

export default JWTContext;
