// Fetch Roles List
export function getPlansList({
    limit = 5,
    page = 0,
    searchParams = {}, // ✅ Always an object
    orderBy = 'id',
    order = 'asc',
    pagination = true
} = {}) {
    return async (dispatch) => {
        const queryParams = { pagination, limit, page, orderBy, order, ...searchParams };
        await apiCall(dispatch, slice.actions.getPlansListSuccess, 'GET', '/membership', queryParams);
    };
}

