import axios from 'axios';

// Create an Axios instance
const apiClient = axios.create({
    baseURL: 'https://13.53.197.110:3001/',
    timeout: 10000,
    headers: {
        'Content-Type': 'application/json'
    }
});

// Optional: Add request interceptor to include auth tokens if needed
apiClient.interceptors.request.use((config) => {
    const token = localStorage.getItem('authToken');
    if (token) {
        config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
});

// Add response interceptor to handle errors globally
apiClient.interceptors.response.use(
    (response) => {
        if (response.data && response.data.success) {
            return {
                success: response.data.success,
                statusCode: response.status,
                message: response.data.message,
                data: response.data?.requestData?.data || null, // Extract request data
                total: response?.data?.requestData?.meta?.total || null,
                page: response?.data?.requestData?.meta?.page,
                pages: response?.data?.requestData?.meta?.pages || null,
                timestamp: response.data.timestamp,
                path: response.config.url
            };
        }

        // If the response format doesn't match, return the raw response
        return response;
    }, // Pass the data directly in successful responses
    (error) => {
        // Handle errors with structured response
        if (error.response && error.response.data) {
            const { status, data } = error.response;

            // Reject with a custom structured error
            const errorObject = {
                success: false,
                statusCode: status,
                message: data.message || 'An error occurred',
                errors: data.message || null, // Detailed validation errors
                timestamp: data.timestamp || new Date().toISOString(),
                path: data.path || error.config.url
            };

            // Ensure ESLint compliance with `prefer-promise-reject-errors`
            return Promise.reject(new Error(JSON.stringify(errorObject)));
        }

        // Reject with a generic error if response is not structured
        return Promise.reject(new Error(error.message || 'An unexpected error occurred'));
    }
);

/**
 * Generic API Request Handler
 * @param {string} method - HTTP method (GET, POST, PUT, DELETE, etc.)
 * @param {string} url - API endpoint (relative to baseURL)
 * @param {Object} [data] - Request payload for POST, PUT, PATCH
 * @param {Object} [params] - Query parameters for GET, DELETE
 * @param {Object} [headers] - Additional request headers
 * @returns {Promise<Object>} - Resolves with API response data
 */
const ApiRequest = async (method, url, data = {}, params = {}, headers = {}, options = {}) => {
    if (!['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'].includes(method.toUpperCase())) {
        throw new Error(`Invalid HTTP method: ${method}`);
    }
    try {
        const config = {
            method: method.toUpperCase(),
            url,
            data,
            params,
            headers,
            timeout: options.timeout || 300000, // Default timeout
            ...options
        };

        const response = await apiClient(config);
        return response;
    } catch (error) {
        // Handle different error types
        if (error.code === 'ECONNABORTED') {
            throw new Error(`Request timed out after ${options.timeout || 10000}ms`);
        }

        if (error.response) {
            // Server responded with error status (4xx, 5xx)
            const { status, data } = error.response;
            throw new Error(data.message || `Request failed with status ${status}`);
        }

        if (error.request) {
            // Request was made but no response received
            throw new Error('No response received from server');
        }

        // Other errors (config issues, etc)
        throw new Error(error.message || 'An unexpected error occurred');
    }
};
export default ApiRequest;
