import { createSlice } from '@reduxjs/toolkit';
import ApiRequest from 'utils/apiService';

// ----------------------------------------------------------------------

const initialState = {
    error: null,
    entities: {
        users: [],
        roles: [],
        permissions: []
    },
    pagination: {
        users: { total: 0, page: 0 },
        roles: { total: 0, page: 0 },
        permissions: { total: 0, page: 0 }
    }
};

const slice = createSlice({
    name: 'usersList',
    initialState,
    reducers: {
        hasError(state, action) {
            state.error = action.payload;
        },

        getUsersListSuccess(state, action) {
            const { data = [], total = 0, page = 0 } = action.payload;
            state.entities.users = data;
            state.pagination.users = { total, page: Number(page) };
        },

        getRolesListSuccess(state, action) {
            const { data = [], total = 0, page = 0 } = action.payload;
            state.entities.roles = data;
            state.pagination.roles = { total, page: Number(page) };
        },

        getPermissionListSuccess(state, action) {
            const { data = [], total = 0, page = 0 } = action.payload;
            state.entities.permissions = data;
            state.pagination.permissions = { total, page: Number(page) };
        }
    }
});

// Reducer
export default slice.reducer;

export async function apiCall(dispatch, action, method, endpoint, queryParams = {}) {
    try {
        if (queryParams.pagination === undefined) {
            queryParams.pagination = true;
        }
        // ✅ Convert queryParams to a properly formatted query string using `URLSearchParams`
        const queryString = new URLSearchParams(queryParams).toString();

        // ✅ Proper request structure with correctly formatted query params
        const response = await ApiRequest(method, `${endpoint}?${queryString}`);

        if (!response || !response.data) {
            throw new Error('Invalid API response');
        }

        dispatch(
            action({
                data: response.data,
                total: response?.total || response.data.length || 0,
                page: response.page
            })
        );
    } catch (error) {
        dispatch(slice.actions.hasError(error.message || 'Unknown error occurred'));
    }
}

// Fetch Users List
export function getUsersList({
    limit = 5,
    page = 0,
    searchParams = {}, // ✅ Always an object
    orderBy = 'id',
    order = 'asc',
    pagination = true
} = {}) {
    console.log('searchQuery', searchParams);
    return async (dispatch) => {
        const queryParams = {
            pagination,
            limit,
            page,
            orderBy,
            order,
            ...searchParams
        };
        await apiCall(dispatch, slice.actions.getUsersListSuccess, 'GET', '/users', queryParams);
    };
}

// Fetch Roles List
export function getRolesList({ limit = 5, page = 0, searchQuery = '', orderBy = 'id', order = 'asc', pagination = true, roleName } = {}) {
    return async (dispatch) => {
        const queryParams = { pagination };

        if (pagination) {
            Object.assign(queryParams, { limit, page, search: searchQuery, orderBy, order });
        }

        if (roleName && roleName !== 'undefined') {
            queryParams.roleName = roleName;
        }
        await apiCall(dispatch, slice.actions.getRolesListSuccess, 'GET', '/users/roles', queryParams);
    };
}

export function geAllPermission({ limit = 10, page = 0, searchQuery = '', orderBy = 'id', order = 'asc', pagination = true } = {}) {
    return async (dispatch) => {
        const queryParams = { pagination };

        if (pagination) {
            Object.assign(queryParams, { limit, page, search: searchQuery, orderBy, order });
        }
        await apiCall(dispatch, slice.actions.getPermissionListSuccess, 'GET', '/users/permission', queryParams);
    };
}
