import { createSlice } from '@reduxjs/toolkit';
import ApiRequest from 'utils/apiService';

// ----------------------------------------------------------------------

const initialState = {
    error: null,
    entities: {
        inquires: []
    },
    pagination: {
        inquires: { total: 0, page: 0 }
    }
};

const slice = createSlice({
    name: 'inquires',
    initialState,
    reducers: {
        hasError(state, action) {
            state.error = action.payload;
        },

        getInquriesListSuccess(state, action) {
            const { data = [], total = 0, page = 0 } = action.payload;
            state.entities.inquires = data;
            state.pagination.inquires = { total, page: Number(page) };
        }
    }
});

// Reducer
export default slice.reducer;

/**
 * API Call Wrapper
 * @param {Function} dispatch - Redux dispatch function
 * @param {Function} action - Redux action to handle response
 * @param {String} method - HTTP Method (GET, POST, etc.)
 * @param {String} endpoint - API endpoint
 * @param {Object} queryParams - Query parameters
 */
export async function apiCall(dispatch, action, method, endpoint, queryParams = {}) {
    try {
        if (queryParams.pagination === undefined) {
            queryParams.pagination = true;
        }

        // ✅ Convert queryParams to a properly formatted query string
        const queryString = new URLSearchParams(queryParams).toString();
        const response = await ApiRequest(method, `${endpoint}?${queryString}`);

        if (!response || !response.data) {
            throw new Error('Invalid API response');
        }

        dispatch(
            action({
                data: response.data,
                total: response?.total || response.data.length || 0,
                page: response.page
            })
        );
    } catch (error) {
        dispatch(slice.actions.hasError(error.message || 'Unknown error occurred'));
    }
}

/**
 * Fetch Inquiries List with Search Parameters Support
 * @param {Object} params - API parameters
 */
export function getInquriesList({
    limit = 5,
    page = 0,
    searchParams = {}, // ✅ Always an object
    orderBy = 'id',
    order = 'asc',
    pagination = true
} = {}) {
    return async (dispatch) => {
        const queryParams = { pagination, limit, page, orderBy, order, ...searchParams };
        await apiCall(dispatch, slice.actions.getInquriesListSuccess, 'GET', '/inquires', queryParams);
    };
}
