import { useTheme } from '@mui/material/styles';
import PropTypes from 'prop-types';

// Import all logos
import logoDark from 'assets/images/logo/socialhype-logo-dark.png';
import logo from 'assets/images/logo/main-web-logo.png';
import Headerlogo from 'assets/images/landing/header-logo.png';
import Dashboardlogo from 'assets/images/landing/dashboard-sh-logo.png';

// Logo configuration
const LOGO_CONFIG = {
    dashboard: {
        src: Dashboardlogo,
        width: 50,
        style: { margin: '0 3rem 0 0' }
    },
    header: {
        src: Headerlogo,
        width: 70
    },
    default: {
        light: {
            src: logo,
            width: 220
        },
        dark: {
            src: logoDark,
            width: 220
        }
    }
};

const Logo = ({ forceLight = false, headerlog = false, dashboardlogo = false }) => {
    const theme = useTheme();

    // Determine which logo to display based on props
    if (dashboardlogo) {
        return (
            <img src={LOGO_CONFIG.dashboard.src} alt="socialhype" width={LOGO_CONFIG.dashboard.width} style={LOGO_CONFIG.dashboard.style} />
        );
    }

    if (headerlog) {
        return <img src={LOGO_CONFIG.header.src} alt="socialhype" width={LOGO_CONFIG.header.width} />;
    }

    // Determine logo type without nested ternaries
    let logoType = 'light';
    if (!forceLight) {
        logoType = 'dark';
    }

    const { src, width } = LOGO_CONFIG.default[logoType];
    return <img src={src} alt="socialhype" width={width} />;
};

Logo.propTypes = {
    forceLight: PropTypes.bool,
    headerlog: PropTypes.bool,
    dashboardlogo: PropTypes.bool
};

export default Logo;
